mapper.select:
select 
from (

    select * from orders
    where userId = #{userId}

        and orderState = #{orderState}

    order by orderId desc
    limit #{offset}, #{pageSize}
) o
left join business b on b.businessId = o.businessId
left join orderDetailet od on od.orderId = o.orderId
left join food f on f.foodId = od.foodId
order by o.orderId desc

select count(*) from orders
where userId = #{userId}

    and orderState = #{orderState}
